feature:
|
          RAW='${{ toJson(github.event.client_payload) }}'

          # Normalize payload
          if [ "$RAW" = "null" ] || [ -z "$RAW" ]; then
            echo '{"_empty": true}' > payload.json
          else
            echo "$RAW" > payload.json
          fi

          node - <<'NODE'
          const fs = require('fs');

          let data;
          try {
            data = JSON.parse(fs.readFileSync('payload.json','utf8'));
          } catch (e) {
            console.error("Malformed JSON");
            process.exit(1);
          }

          // Reject null explicitly
          if (data === null) {
            console.error("Null payload rejected");
            process.exit(1);
          }

          // Allow empty but mark it
          if (data._empty === true) {
            console.log("Empty witness accepted.");
            process.exit(0);
          }

          // Reject empty object (silent noise)
          if (typeof data === 'object' && Object.keys(data).length === 0) {
            console.error("Empty object payload rejected");
            process.exit(1);
          }

          // Size guard
          const size = JSON.stringify(data).length;
          if (size > 5000) {
            console.error("Payload too large");
            process.exit(1);
          }

          console.log("Payload validated.");
          NODE

verify:
  runs-on: ubuntu-latest

  steps:
    - uses: actions/checkout@v4

    - name: Use Node 18
      uses: actions/setup-node@v4
      with:
        node-version: 18.20.8

    - name: Install dependencies
      run: npm install

    - name: Regenerate report
      run: node core-scientific/publication-gate/generate-report.cjs

    - name: Verify integrity  
      run: |
        node - <<'NODE'
        const fs = require('fs');
        const crypto = require('crypto');

        function canonicalize(obj) {
          if (Array.isArray(obj)) {
            return obj.map(canonicalize);
          }
          if (obj !== null && typeof obj === 'object') {
            return Object.keys(obj)
              .sort()
              .reduce((acc, key) => {
                acc[key] = canonicalize(obj[key]);
                return acc;
              }, {});
          }
          return obj;
        }

        const reportPath = './core-scientific/publication-gate/report.json';
        const generatorPath = './core-scientific/publication-gate/generate-report.cjs';

        if (!fs.existsSync(reportPath)) {
          console.error('report.json missing.');
          process.exit(1);
        }

        const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));

        const originalReportHash = report.reportHash;
        const originalGeneratorHash = report.generatorHash;

        const cloned = JSON.parse(JSON.stringify(report));
        delete cloned.reportHash;

        const canonicalCloned = canonicalize(cloned);

        const recomputedReportHash = crypto
          .createHash('sha256')
          .update(JSON.stringify(canonicalCloned))
          .digest('hex');

        if (originalReportHash !== recomputedReportHash) {
          console.error('Report hash mismatch.');
          process.exit(1);
        }

        const currentGeneratorHash = crypto
          .createHash('sha256')
          .update(
            fs.readFileSync(generatorPath, 'utf8').replace(/\r/g, '')
          )
          .digest('hex');

        if (originalGeneratorHash !== currentGeneratorHash) {
          console.error('Generator drift detected.');
          process.exit(1);
        }

        console.log('All integrity checks passed.');
        NODE
